export function getDefaultPermissionsForRole(role: UserRole): AppModuleId[] {
  if (role === 'ADMIN') {
    return APP_MODULES.map(m => m.id);
  }
  if (role === 'BACKOFFICE') {
    return [
      'dashboard',
      'calendar',
      'property',
      'devices',
      'cctv',
      'evaluation',
      'issues',
      'readiness',
      'evidence',
    ];
  }
  // TEKNISI: Operasional lapangan (visit gedung, perangkat, CCTV, QC testing, kendala, bukti)
  return [
    'property',
    'devices',
    'cctv',
    'evaluation',
    'issues',
    'evidence',
  ];
}

